mapper.select:
SELECT STAY_DATE, TOTAL_QTY, SOLD_QTY, PRICE_AMT, CLOSED_YN
  FROM ROOM_CALENDAR
 WHERE ROOM_SN = #{roomSn}
   AND STAY_DATE >= #{checkIn}
   AND STAY_DATE < #{checkOut}
 ORDER BY STAY_DATE

SELECT RESERVATION_SN
  FROM RESERVATION
 WHERE RESERVER_USER_SN = #{userSn}
   AND IDEMPOTENCY_KEY = #{idemHash}
 LIMIT 1

mapper.insert:
INSERT INTO RESERVATION_ITEM (
    RESERVATION_SN, ROOM_SN, ROOM_NM_SNAP, ITEM_AMT, ROOM_QTY, REG_DT, RGTR_SN, MDFCN_DT
) VALUES (
    #{reservationSn}, #{roomSn}, #{roomNmSnap}, #{itemAmt}, #{roomQty}, UTC_TIMESTAMP(6), #{rgtrSn}, UTC_TIMESTAMP(6)
)

INSERT INTO RESERVATION_ITEM_NIGHT (
    RESERVATION_ITEM_SN, STAY_DATE, NIGHT_PRICE_AMT, NIGHT_QTY, REG_DT, RGTR_SN, MDFCN_DT
) VALUES (
    #{reservationItemSn}, #{stayDate}, #{nightPriceAmt}, #{nightQty}, UTC_TIMESTAMP(6), #{rgtrSn}, UTC_TIMESTAMP(6)
)

INSERT INTO RESERVATION_AGRE (
    RESERVATION_SN, TRMS_SN, TRMS_VER_NO, AGRE_PRPS_CD, AGRE_ITEM_CN, AGRE_DT, REG_DT, RGTR_SN, MDFCN_DT
) VALUES (
    #{reservationSn}, #{trmsSn}, #{trmsVerNo}, #{agrePrpsCd}, #{agreItemCn}, #{agreDt},
    UTC_TIMESTAMP(6), #{rgtrSn}, UTC_TIMESTAMP(6)
)

mapper.select:
SELECT 
  FROM RESERVATION
 WHERE RESERVATION_SN = #{reservationSn}
   AND RESERVER_USER_SN = #{userSn}
   AND DEL_YN = 'N'

mapper.update:
UPDATE ROOM_CALENDAR
   SET SOLD_QTY = SOLD_QTY + #{qty},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE ROOM_SN = #{roomSn}
   AND STAY_DATE = #{stayDate}
   AND CLOSED_YN = 'N'
   AND (TOTAL_QTY - SOLD_QTY) >= #{qty}

UPDATE RESERVATION
   SET RESERVATION_STTS_CD = 'RESERVED',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE RESERVATION_SN = #{reservationSn}
   AND RESERVATION_STTS_CD IN ('HOLD','PAYMENT_PENDING')
